const AE_L=(x1,y1,x2,y2,col=AE_GR,w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const AE_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}" ${o.ex||''}/>`;
const AE_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=160)=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push(`${(x0+(x1-x0)*i/n).toFixed(1)},${(yc-k*f(t)).toFixed(1)}`)}return `<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"/>`};
const AE_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return AE_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const AE_sub=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
/* a toothed wheel: z pitches, the indices in miss left out (index 0 at the top), teeth th deep */
const AE_wheel=(cx,cy,r,z,miss,col,th=12,fill='#FFFFFF')=>{let s=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="${fill}" stroke="${col}" stroke-width="3"/>`;
 for(let i=0;i<z;i++){if(miss.includes(i))continue;const a0=(-90+(i-.25)*360/z)*Math.PI/180,a1=(-90+(i+.25)*360/z)*Math.PI/180;
  const P4=[[r,a0],[r+th,a0],[r+th,a1],[r,a1]].map(([q,a])=>`${(cx+q*Math.cos(a)).toFixed(1)},${(cy+q*Math.sin(a)).toFixed(1)}`).join(' ');
  s+=`<polygon points="${P4}" fill="${col}" fill-opacity=".85"/>`}
 return s+`<circle cx="${cx}" cy="${cy}" r="${Math.max(6,r*.18)}" fill="${col}" fill-opacity=".35"/>`};
/* a digital pulse train: one character per pitch p ('1' a tooth: high for the first half; '0' an empty slot) */
const AE_train=(x0,ylow,p,h,pat,col,w=4)=>{let x=x0,pts=[`${x0},${ylow}`];for(const ch of pat){if(ch==='1')pts.push(`${x},${ylow-h}`,`${x+p/2},${ylow-h}`,`${x+p/2},${ylow}`);x+=p;pts.push(`${x},${ylow}`)}
 return `<polyline points="${pts.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round"/>`};
/* a bracket with end ticks */
const AE_br=(x1,x2,y,col,w=3)=>AE_L(x1,y,x2,y,col,w)+AE_L(x1,y-10,x1,y+10,col,w)+AE_L(x2,y-10,x2,y+10,col,w);
/* a straight pipe section with air arrows */
const AE_pipe=(x,y,w,h)=>AE_box(x,y,w,h,{fill:'#EDF2FF',st:BLU,r:10});
const AE_vort=(x,y,r,col,up,w=4)=>`<path d="M${x-r},${y} A${r},${r} 0 1,${up?1:0} ${x},${y+(up?r:-r)}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/>`;
/* a short tooth rack for the gap traps: present teeth at pitch p, the missing ones skipped */
